let file = """{"version":3,"file":"ColorPicker-avnyvKDr.js","names":["$props"],"sources":["../../src/components/ui/color-picker/ColorPickerSaturationValue.vue","../../src/components/ui/color-picker/ColorPickerSaturationValue.vue","../../src/components/ui/color-picker/ColorPickerSlider.vue","../../src/components/ui/color-picker/ColorPickerSlider.vue","../../src/components/ui/color-picker/useColorPicker.ts","../../src/components/ui/color-picker/ColorPickerPanel.vue","../../src/components/ui/color-picker/ColorPickerPanel.vue","../../src/components/ui/color-picker/ColorPicker.vue","../../src/components/ui/color-picker/ColorPicker.vue"],"sourcesContent":["<script setup lang=\"ts\">\nimport { computed, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nconst { t } = useI18n()\n\nconst { hue } = defineProps<{\n  hue: number\n}>()\n\nconst saturation = defineModel<number>('saturation', { required: true })\nconst value = defineModel<number>('value', { required: true })\n\nconst containerRef = ref<HTMLElement | null>(null)\n\nconst hueBackground = computed(() => `hsl(${hue}, 100%, 50%)`)\n\nconst handleStyle = computed(() => ({\n  left: `${saturation.value}%`,\n  top: `${100 - value.value}%`\n}))\n\nfunction updateFromPointer(e: PointerEvent) {\n  const el = containerRef.value\n  if (!el) return\n  const rect = el.getBoundingClientRect()\n  const x = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width))\n  const y = Math.max(0, Math.min(1, (e.clientY - rect.top) / rect.height))\n  saturation.value = Math.round(x * 100)\n  value.value = Math.round((1 - y) * 100)\n}\n\nfunction handlePointerDown(e: PointerEvent) {\n  ;(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId)\n  updateFromPointer(e)\n}\n\nfunction handlePointerMove(e: PointerEvent) {\n  if (!(e.currentTarget as HTMLElement).hasPointerCapture(e.pointerId)) return\n  updateFromPointer(e)\n}\n</script>\n\n<template>\n  <div\n    ref=\"containerRef\"\n    role=\"slider\"\n    :aria-label=\"t('color.saturationBrightness')\"\n    :aria-valuetext=\"`${saturation}%, ${value}%`\"\n    class=\"relative aspect-square w-full cursor-crosshair rounded-sm\"\n    :style=\"{ backgroundColor: hueBackground, touchAction: 'none' }\"\n    @pointerdown=\"handlePointerDown\"\n    @pointermove=\"handlePointerMove\"\n  >\n    <div\n      class=\"absolute inset-0 rounded-sm bg-linear-to-r from-white to-transparent\"\n    />\n    <div\n      class=\"absolute inset-0 rounded-sm bg-linear-to-b from-transparent to-black\"\n    />\n    <div\n      class=\"pointer-events-none absolute size-3.5 -translate-1/2 rounded-full border-2 border-white shadow-[0_0_2px_rgba(0,0,0,0.6)]\"\n      :style=\"handleStyle\"\n    />\n  </div>\n</template>\n","<script setup lang=\"ts\">\nimport { computed, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nconst { t } = useI18n()\n\nconst { hue } = defineProps<{\n  hue: number\n}>()\n\nconst saturation = defineModel<number>('saturation', { required: true })\nconst value = defineModel<number>('value', { required: true })\n\nconst containerRef = ref<HTMLElement | null>(null)\n\nconst hueBackground = computed(() => `hsl(${hue}, 100%, 50%)`)\n\nconst handleStyle = computed(() => ({\n  left: `${saturation.value}%`,\n  top: `${100 - value.value}%`\n}))\n\nfunction updateFromPointer(e: PointerEvent) {\n  const el = containerRef.value\n  if (!el) return\n  const rect = el.getBoundingClientRect()\n  const x = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width))\n  const y = Math.max(0, Math.min(1, (e.clientY - rect.top) / rect.height))\n  saturation.value = Math.round(x * 100)\n  value.value = Math.round((1 - y) * 100)\n}\n\nfunction handlePointerDown(e: PointerEvent) {\n  ;(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId)\n  updateFromPointer(e)\n}\n\nfunction handlePointerMove(e: PointerEvent) {\n  if (!(e.currentTarget as HTMLElement).hasPointerCapture(e.pointerId)) return\n  updateFromPointer(e)\n}\n</script>\n\n<template>\n  <div\n    ref=\"containerRef\"\n    role=\"slider\"\n    :aria-label=\"t('color.saturationBrightness')\"\n    :aria-valuetext=\"`${saturation}%, ${value}%`\"\n    class=\"relative aspect-square w-full cursor-crosshair rounded-sm\"\n    :style=\"{ backgroundColor: hueBackground, touchAction: 'none' }\"\n    @pointerdown=\"handlePointerDown\"\n    @pointermove=\"handlePointerMove\"\n  >\n    <div\n      class=\"absolute inset-0 rounded-sm bg-linear-to-r from-white to-transparent\"\n    />\n    <div\n      class=\"absolute inset-0 rounded-sm bg-linear-to-b from-transparent to-black\"\n    />\n    <div\n      class=\"pointer-events-none absolute size-3.5 -translate-1/2 rounded-full border-2 border-white shadow-[0_0_2px_rgba(0,0,0,0.6)]\"\n      :style=\"handleStyle\"\n    />\n  </div>\n</template>\n","<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { hsbToRgb, rgbToHex } from '@/utils/colorUtil'\n\nconst { t } = useI18n()\n\nconst {\n  type,\n  hue = 0,\n  saturation = 100,\n  brightness = 100\n} = defineProps<{\n  type: 'hue' | 'alpha'\n  hue?: number\n  saturation?: number\n  brightness?: number\n}>()\n\nconst modelValue = defineModel<number>({ required: true })\n\nconst max = computed(() => (type === 'hue' ? 360 : 100))\n\nconst fraction = computed(() => modelValue.value / max.value)\n\nconst trackBackground = computed(() => {\n  if (type === 'hue') {\n    return 'linear-gradient(to right, #f00 0%, #ff0 17%, #0f0 33%, #0ff 50%, #00f 67%, #f0f 83%, #f00 100%)'\n  }\n  const rgb = hsbToRgb({ h: hue, s: saturation, b: brightness })\n  const hex = rgbToHex(rgb)\n  return `linear-gradient(to right, transparent, ${hex})`\n})\n\nconst containerStyle = computed(() => {\n  if (type === 'alpha') {\n    return {\n      backgroundImage:\n        'repeating-conic-gradient(#808080 0% 25%, transparent 0% 50%)',\n      backgroundSize: '8px 8px',\n      touchAction: 'none'\n    }\n  }\n  return {\n    background: trackBackground.value,\n    touchAction: 'none'\n  }\n})\n\nfunction updateFromPointer(e: PointerEvent) {\n  const el = e.currentTarget as HTMLElement\n  const rect = el.getBoundingClientRect()\n  const x = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width))\n  modelValue.value = Math.round(x * max.value)\n}\n\nfunction handlePointerDown(e: PointerEvent) {\n  ;(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId)\n  updateFromPointer(e)\n}\n\nfunction handlePointerMove(e: PointerEvent) {\n  if (!(e.currentTarget as HTMLElement).hasPointerCapture(e.pointerId)) return\n  updateFromPointer(e)\n}\n</script>\n\n<template>\n  <div\n    role=\"slider\"\n    :aria-label=\"type === 'hue' ? t('color.hue') : t('color.alpha')\"\n    :aria-valuemin=\"0\"\n    :aria-valuemax=\"max\"\n    :aria-valuenow=\"modelValue\"\n    class=\"relative flex h-4 cursor-pointer items-center rounded-full p-px\"\n    :style=\"containerStyle\"\n    @pointerdown=\"handlePointerDown\"\n    @pointermove=\"handlePointerMove\"\n  >\n    <div\n      v-if=\"type === 'alpha'\"\n      class=\"absolute inset-0 rounded-full\"\n      :style=\"{ background: trackBackground }\"\n    />\n    <div\n      class=\"pointer-events-none absolute aspect-square h-full -translate-x-1/2 rounded-full border-2 border-white shadow-[0_0_2px_rgba(0,0,0,0.6)]\"\n      :style=\"{ left: `${fraction * 100}%` }\"\n    />\n  </div>\n</template>\n","<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { hsbToRgb, rgbToHex } from '@/utils/colorUtil'\n\nconst { t } = useI18n()\n\nconst {\n  type,\n  hue = 0,\n  saturation = 100,\n  brightness = 100\n} = defineProps<{\n  type: 'hue' | 'alpha'\n  hue?: number\n  saturation?: number\n  brightness?: number\n}>()\n\nconst modelValue = defineModel<number>({ required: true })\n\nconst max = computed(() => (type === 'hue' ? 360 : 100))\n\nconst fraction = computed(() => modelValue.value / max.value)\n\nconst trackBackground = computed(() => {\n  if (type === 'hue') {\n    return 'linear-gradient(to right, #f00 0%, #ff0 17%, #0f0 33%, #0ff 50%, #00f 67%, #f0f 83%, #f00 100%)'\n  }\n  const rgb = hsbToRgb({ h: hue, s: saturation, b: brightness })\n  const hex = rgbToHex(rgb)\n  return `linear-gradient(to right, transparent, ${hex})`\n})\n\nconst containerStyle = computed(() => {\n  if (type === 'alpha') {\n    return {\n      backgroundImage:\n        'repeating-conic-gradient(#808080 0% 25%, transparent 0% 50%)',\n      backgroundSize: '8px 8px',\n      touchAction: 'none'\n    }\n  }\n  return {\n    background: trackBackground.value,\n    touchAction: 'none'\n  }\n})\n\nfunction updateFromPointer(e: PointerEvent) {\n  const el = e.currentTarget as HTMLElement\n  const rect = el.getBoundingClientRect()\n  const x = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width))\n  modelValue.value = Math.round(x * max.value)\n}\n\nfunction handlePointerDown(e: PointerEvent) {\n  ;(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId)\n  updateFromPointer(e)\n}\n\nfunction handlePointerMove(e: PointerEvent) {\n  if (!(e.currentTarget as HTMLElement).hasPointerCapture(e.pointerId)) return\n  updateFromPointer(e)\n}\n</script>\n\n<template>\n  <div\n    role=\"slider\"\n    :aria-label=\"type === 'hue' ? t('color.hue') : t('color.alpha')\"\n    :aria-valuemin=\"0\"\n    :aria-valuemax=\"max\"\n    :aria-valuenow=\"modelValue\"\n    class=\"relative flex h-4 cursor-pointer items-center rounded-full p-px\"\n    :style=\"containerStyle\"\n    @pointerdown=\"handlePointerDown\"\n    @pointermove=\"handlePointerMove\"\n  >\n    <div\n      v-if=\"type === 'alpha'\"\n      class=\"absolute inset-0 rounded-full\"\n      :style=\"{ background: trackBackground }\"\n    />\n    <div\n      class=\"pointer-events-none absolute aspect-square h-full -translate-x-1/2 rounded-full border-2 border-white shadow-[0_0_2px_rgba(0,0,0,0.6)]\"\n      :style=\"{ left: `${fraction * 100}%` }\"\n    />\n  </div>\n</template>\n","import { clamp } from 'es-toolkit'\nimport type { Ref } from 'vue'\nimport { computed, reactive, ref, watch } from 'vue'\n\nimport type { HSVA } from '@/utils/colorUtil'\nimport {\n  hexToHsva,\n  hsbToRgb,\n  normalizeHex,\n  rgbToHex,\n  rgbToHsv\n} from '@/utils/colorUtil'\n\nexport const rgbChannels = [\n  { key: 'r', label: 'color.red' },\n  { key: 'g', label: 'color.green' },\n  { key: 'b', label: 'color.blue' }\n] as const\n\nfunction useDraftField<T>(source: () => T, apply: (draft: T) => void) {\n  const draft = ref(source()) as Ref<T>\n  const isEditing = ref(false)\n\n  watch(source, (value) => {\n    if (!isEditing.value) draft.value = value\n  })\n\n  return reactive({\n    draft,\n    beginEdit: () => {\n      isEditing.value = true\n    },\n    commit: () => apply(draft.value),\n    reset: () => {\n      isEditing.value = false\n      draft.value = source()\n    }\n  })\n}\n\nexport function useColorPicker(hsva: Ref<HSVA>) {\n  const rgb = computed(() =>\n    hsbToRgb({ h: hsva.value.h, s: hsva.value.s, b: hsva.value.v })\n  )\n  const hexString = computed(() => rgbToHex(rgb.value).toLowerCase())\n\n  const hex = useDraftField(\n    () => hexString.value,\n    (draft) => {\n      const normalized = normalizeHex(draft)\n      if (!normalized) return\n      const next = hexToHsva(normalized)\n      hsva.value = { ...hsva.value, h: next.h, s: next.s, v: next.v }\n    }\n  )\n\n  const rgbField = useDraftField(\n    () => ({ ...rgb.value }),\n    ({ r, g, b }) => {\n      if (![r, g, b].every(Number.isFinite)) return\n      const hsv = rgbToHsv({\n        r: clamp(Math.round(r), 0, 255),\n        g: clamp(Math.round(g), 0, 255),\n        b: clamp(Math.round(b), 0, 255)\n      })\n      hsva.value = { ...hsva.value, h: hsv.h, s: hsv.s, v: hsv.v }\n    }\n  )\n\n  const alpha = useDraftField(\n    () => hsva.value.a,\n    (draft) => {\n      if (!Number.isFinite(draft)) return\n      hsva.value = { ...hsva.value, a: clamp(Math.round(draft), 0, 100) }\n    }\n  )\n\n  return { hex, rgb: rgbField, alpha }\n}\n","<template>\n  <div\n    class=\"flex w-[211px] flex-col gap-2 rounded-lg border border-border-subtle bg-base-background p-2 shadow-md\"\n  >\n    <ColorPickerSaturationValue\n      v-model:saturation=\"hsva.s\"\n      v-model:value=\"hsva.v\"\n      :hue=\"hsva.h\"\n    />\n    <ColorPickerSlider v-model=\"hsva.h\" type=\"hue\" />\n    <ColorPickerSlider\n      v-if=\"alpha\"\n      v-model=\"hsva.a\"\n      type=\"alpha\"\n      :hue=\"hsva.h\"\n      :saturation=\"hsva.s\"\n      :brightness=\"hsva.v\"\n    />\n    <div class=\"flex items-center gap-1\">\n      <Select v-model=\"displayMode\">\n        <SelectTrigger\n          class=\"h-6 w-[58px] shrink-0 gap-0.5 overflow-clip rounded-sm border-0 px-1.5 py-0 text-xs [&>span]:overflow-visible\"\n        >\n          <SelectValue />\n        </SelectTrigger>\n        <SelectContent class=\"min-w-16 p-1\">\n          <SelectItem value=\"hex\" class=\"px-2 py-1 text-xs\">\n            {{ t('color.hex') }}\n          </SelectItem>\n          <SelectItem value=\"rgba\" class=\"px-2 py-1 text-xs\">\n            {{ t('color.rgba') }}\n          </SelectItem>\n        </SelectContent>\n      </Select>\n      <div\n        class=\"flex h-6 min-w-0 flex-1 items-center gap-1 rounded-sm bg-secondary-background px-1 text-xs text-muted-foreground\"\n      >\n        <template v-if=\"displayMode === 'hex'\">\n          <input\n            v-model=\"hex.draft\"\n            type=\"text\"\n            spellcheck=\"false\"\n            :aria-label=\"t('color.hex')\"\n            class=\"min-w-0 flex-1 appearance-none border-none bg-transparent p-0 text-center outline-none\"\n            @focus=\"hex.beginEdit\"\n            @input=\"hex.commit\"\n            @keydown.enter=\"hex.commit\"\n            @blur=\"hex.reset\"\n          />\n        </template>\n        <template v-else>\n          <input\n            v-for=\"channel in rgbChannels\"\n            :key=\"channel.key\"\n            v-model.number=\"rgb.draft[channel.key]\"\n            type=\"number\"\n            :min=\"0\"\n            :max=\"255\"\n            :aria-label=\"t(channel.label)\"\n            class=\"min-w-0 flex-1 appearance-none border-none bg-transparent p-0 text-center outline-none [&::-webkit-inner-spin-button]:appearance-none\"\n            @focus=\"rgb.beginEdit\"\n            @input=\"rgb.commit\"\n            @keydown.enter=\"rgb.commit\"\n            @blur=\"rgb.reset\"\n          />\n        </template>\n        <div\n          v-if=\"alpha\"\n          class=\"flex shrink-0 items-center border-l border-border-subtle pl-1\"\n        >\n          <input\n            v-model.number=\"alphaField.draft\"\n            type=\"number\"\n            :min=\"0\"\n            :max=\"100\"\n            :aria-label=\"t('color.alpha')\"\n            class=\"w-6 min-w-0 appearance-none border-none bg-transparent p-0 text-right outline-none [&::-webkit-inner-spin-button]:appearance-none\"\n            @focus=\"alphaField.beginEdit\"\n            @input=\"alphaField.commit\"\n            @keydown.enter=\"alphaField.commit\"\n            @blur=\"alphaField.reset\"\n          />\n          <span>%</span>\n        </div>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useI18n } from 'vue-i18n'\n\nimport Select from '@/components/ui/select/Select.vue'\nimport SelectContent from '@/components/ui/select/SelectContent.vue'\nimport SelectItem from '@/components/ui/select/SelectItem.vue'\nimport SelectTrigger from '@/components/ui/select/SelectTrigger.vue'\nimport SelectValue from '@/components/ui/select/SelectValue.vue'\nimport type { HSVA } from '@/utils/colorUtil'\n\nimport ColorPickerSaturationValue from './ColorPickerSaturationValue.vue'\nimport ColorPickerSlider from './ColorPickerSlider.vue'\nimport { rgbChannels, useColorPicker } from './useColorPicker'\n\nconst { alpha = true } = defineProps<{ alpha?: boolean }>()\n\nconst hsva = defineModel<HSVA>('hsva', { required: true })\nconst displayMode = defineModel<'hex' | 'rgba'>('displayMode', {\n  required: true\n})\n\nconst { t } = useI18n()\n\nconst { hex, rgb, alpha: alphaField } = useColorPicker(hsva)\n</script>\n","<template>\n  <div\n    class=\"flex w-[211px] flex-col gap-2 rounded-lg border border-border-subtle bg-base-background p-2 shadow-md\"\n  >\n    <ColorPickerSaturationValue\n      v-model:saturation=\"hsva.s\"\n      v-model:value=\"hsva.v\"\n      :hue=\"hsva.h\"\n    />\n    <ColorPickerSlider v-model=\"hsva.h\" type=\"hue\" />\n    <ColorPickerSlider\n      v-if=\"alpha\"\n      v-model=\"hsva.a\"\n      type=\"alpha\"\n      :hue=\"hsva.h\"\n      :saturation=\"hsva.s\"\n      :brightness=\"hsva.v\"\n    />\n    <div class=\"flex items-center gap-1\">\n      <Select v-model=\"displayMode\">\n        <SelectTrigger\n          class=\"h-6 w-[58px] shrink-0 gap-0.5 overflow-clip rounded-sm border-0 px-1.5 py-0 text-xs [&>span]:overflow-visible\"\n        >\n          <SelectValue />\n        </SelectTrigger>\n        <SelectContent class=\"min-w-16 p-1\">\n          <SelectItem value=\"hex\" class=\"px-2 py-1 text-xs\">\n            {{ t('color.hex') }}\n          </SelectItem>\n          <SelectItem value=\"rgba\" class=\"px-2 py-1 text-xs\">\n            {{ t('color.rgba') }}\n          </SelectItem>\n        </SelectContent>\n      </Select>\n      <div\n        class=\"flex h-6 min-w-0 flex-1 items-center gap-1 rounded-sm bg-secondary-background px-1 text-xs text-muted-foreground\"\n      >\n        <template v-if=\"displayMode === 'hex'\">\n          <input\n            v-model=\"hex.draft\"\n            type=\"text\"\n            spellcheck=\"false\"\n            :aria-label=\"t('color.hex')\"\n            class=\"min-w-0 flex-1 appearance-none border-none bg-transparent p-0 text-center outline-none\"\n            @focus=\"hex.beginEdit\"\n            @input=\"hex.commit\"\n            @keydown.enter=\"hex.commit\"\n            @blur=\"hex.reset\"\n          />\n        </template>\n        <template v-else>\n          <input\n            v-for=\"channel in rgbChannels\"\n            :key=\"channel.key\"\n            v-model.number=\"rgb.draft[channel.key]\"\n            type=\"number\"\n            :min=\"0\"\n            :max=\"255\"\n            :aria-label=\"t(channel.label)\"\n            class=\"min-w-0 flex-1 appearance-none border-none bg-transparent p-0 text-center outline-none [&::-webkit-inner-spin-button]:appearance-none\"\n            @focus=\"rgb.beginEdit\"\n            @input=\"rgb.commit\"\n            @keydown.enter=\"rgb.commit\"\n            @blur=\"rgb.reset\"\n          />\n        </template>\n        <div\n          v-if=\"alpha\"\n          class=\"flex shrink-0 items-center border-l border-border-subtle pl-1\"\n        >\n          <input\n            v-model.number=\"alphaField.draft\"\n            type=\"number\"\n            :min=\"0\"\n            :max=\"100\"\n            :aria-label=\"t('color.alpha')\"\n            class=\"w-6 min-w-0 appearance-none border-none bg-transparent p-0 text-right outline-none [&::-webkit-inner-spin-button]:appearance-none\"\n            @focus=\"alphaField.beginEdit\"\n            @input=\"alphaField.commit\"\n            @keydown.enter=\"alphaField.commit\"\n            @blur=\"alphaField.reset\"\n          />\n          <span>%</span>\n        </div>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useI18n } from 'vue-i18n'\n\nimport Select from '@/components/ui/select/Select.vue'\nimport SelectContent from '@/components/ui/select/SelectContent.vue'\nimport SelectItem from '@/components/ui/select/SelectItem.vue'\nimport SelectTrigger from '@/components/ui/select/SelectTrigger.vue'\nimport SelectValue from '@/components/ui/select/SelectValue.vue'\nimport type { HSVA } from '@/utils/colorUtil'\n\nimport ColorPickerSaturationValue from './ColorPickerSaturationValue.vue'\nimpo